ALTER TABLE resumes ADD COLUMN current_revision_id TEXT;
CREATE TABLE resume_revisions (id TEXT PRIMARY KEY, resume_id TEXT NOT NULL REFERENCES resumes(id) ON DELETE CASCADE, revision INTEGER NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('working','submitted')), document_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(resume_id, revision));
CREATE TABLE source_materials (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id) ON DELETE SET NULL, title TEXT, content TEXT NOT NULL, content_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE evidence_facts (id TEXT PRIMARY KEY, material_id TEXT NOT NULL REFERENCES source_materials(id), project_id TEXT REFERENCES projects(id) ON DELETE SET NULL, text TEXT NOT NULL, source_start INTEGER NOT NULL, source_end INTEGER NOT NULL, status TEXT NOT NULL, stage TEXT NOT NULL, revision INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE job_analyses (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES job_targets(id) ON DELETE CASCADE, input_hash TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE tailoring_proposals (id TEXT PRIMARY KEY, resume_id TEXT NOT NULL REFERENCES resumes(id) ON DELETE CASCADE, job_id TEXT NOT NULL REFERENCES job_targets(id) ON DELETE CASCADE, analysis_id TEXT NOT NULL REFERENCES job_analyses(id), input_hash TEXT NOT NULL, base_revision INTEGER NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL);
